<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Snake Game</title>
    <style>
        body {
            background-color: #121212;
            color: #ffffff;
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
            overflow: hidden;
        }
        #game-container {
            text-align: center;
        }
        h1 {
            margin-bottom: 10px;
            color: #4CAF50;
        }
        #score {
            font-size: 24px;
            margin-bottom: 10px;
            font-weight: bold;
        }
        canvas#snake {
            background-color: #222;
            border: 4px solid #444;
            box-shadow: 0 0 20px rgba(0,0,0,0.5);
            display: block;
        }
        .controls {
            margin-top: 20px;
        }
        button {
            background-color: #444;
            color: white;
            border: none;
            padding: 10px 20px;
            margin: 0 5px;
            font-size: 16px;
            cursor: pointer;
            border-radius: 4px;
            transition: background-color 0.2s;
        }
        button:hover {
            background-color: #666;
        }
        button#start { background-color: #2e7d32; }
        button#start:hover { background-color: #388e3c; }
        button#pause { background-color: #c62828; }
        button#pause:hover { background-color: #e53935; }
        button#reset { background-color: #1565c0; }
        button#reset:hover { background-color: #1976d2; }
    </style>
</head>
<body>

    <div id="game-container">
        <h1>SNAKE</h1>
        <div id="score">Score: 0</div>
        <canvas id="snake" width="400" height="400"></canvas>
        <div class="controls">
            <button id="start">Start</button>
            <button id="pause">Pause</button>
            <button id="reset">Reset</button>
        </div>
    </div>

    <script>
        (function() {
            const canvas = document.getElementById('snake');
            const ctx = canvas.getContext('2d');
            const scoreEl = document.getElementById('score');
            const startBtn = document.getElementById('start');
            const pauseBtn = document.getElementById('pause');
            const resetBtn = document.getElementById('reset');

            const CELL_COUNT = 20;
            const CELL_SIZE = 400 / CELL_COUNT;

            const directions = {
                up:    { x: 0,  y: -1 },
                down:  { x: 0,  y: 1  },
                left:  { x: -1, y: 0  },
                right: { x: 1,  y: 0  }
            };

            const opposites = {
                up: 'down',
                down: 'up',
                left: 'right',
                right: 'left'
            };

            let gameInstance = null;

            class SnakeGame {
                constructor(w, h) {
                    this.w = w;
                    this.h = h;
                    this.reset();
                }

                reset() {
                    // Snake starts with length 3
                    this.snake = [
                        { x: 5, y: 10 },
                        { x: 5, y: 11 },
                        { x: 5, y: 12 }
                    ];
                    this.food = { x: 12, y: 10 };
                    this.score = 0;
                    this.isAlive = true;
                    this.currentDir = directions.up;
                    this.nextDir = directions.up;
                    this.updateScoreDisplay();
                    this.draw();
                }

                updateScoreDisplay() {
                    scoreEl.textContent = `Score: ${this.score}`;
                }

                setDir(dirName) {
                    const newDir = directions[dirName];
                    if (!newDir) return;

                    const oppositeDir = opposites[dirName];

                    // Ignore 180 degree reversal relative to current direction
                    // and relative to the queued next direction
                    const isOppositeCurrent = (newDir.x === -this.currentDir.x && newDir.y === -this.currentDir.y);
                    const isOppositeNext = (newDir.x === -this.nextDir.x && newDir.y === -this.nextDir.y);

                    if (isOppositeCurrent || isOppositeNext) {
                        return;
                    }

                    this.nextDir = newDir;
                }

                setFood(x, y) {
                    this.food = { x, y };
                    this.draw();
                }

                tick() {
                    if (!this.isAlive) return;

                    // Apply queued direction
                    this.currentDir = this.nextDir;

                    const head = this.snake[0];
                    const newHead = {
                        x: head.x + this.currentDir.x,
                        y: head.y + this.currentDir.y
                    };

                    // Check Wall Collision
                    if (newHead.x < 0 || newHead.x >= this.w || newHead.y < 0 || newHead.y >= this.h) {
                        this.isAlive = false;
                        this.draw();
                        return;
                    }

                    // Check Body Collision
                    // If we hit the tail, it's only a collision if we aren't growing this tick.
                    // However, to simplify and follow the rule "running into its body", 
                    // we check against the current snake body.
                    const isEatingFood = (newHead.x === this.food.x && newHead.y === this.food.y);

                    // Check if newHead hits any part of the snake
                    // If it eats food, the tail won't be removed, so the tail is part of the body.
                    // If it doesn't eat food, the tail will be removed, so hitting the tail is okay.
                    let bodyCollision = false;
                    const bodyEndIndex = isEatingFood ? this.snake.length : this.snake.length - 1;
                    for (let i = 0; i < bodyEndIndex; i++) {
                        if (newHead.x === this.snake[i].x && newHead.y === this.snake[i].y) {
                            bodyCollision = true;
                            break;
                        }
                    }

                    if (bodyCollision) {
                        this.isAlive = false;
                        this.draw();
                        return;
                    }

                    // Move snake
                    this.snake.unshift(newHead);

                    if (isEatingFood) {
                        this.score++;
                        this.updateScoreDisplay();
                        this.generateFood();
                    } else {
                        this.snake.pop();
                    }

                    this.draw();
                }

                generateFood() {
                    let valid = false;
                    while (!valid) {
                        this.food = {
                            x: Math.floor(Math.random() * this.w),
                            y: Math.floor(Math.random() * this.h)
                        };
                        // Ensure food doesn't spawn on snake body
                        valid = !this.snake.some(segment => segment.x === this.food.x && segment.y === this.food.y);
                    }
                }

                // API Methods
                snake() { return this.snake.map(s => [s.x, s.y]); }
                food() { return [this.food.x, this.food.y]; }
                alive() { return this.isAlive; }
                score() { return this.score; }

                draw() {
                    // Clear
                    ctx.clearRect(0, 0, canvas.width, canvas.height);

                    // Draw Food
                    ctx.fillStyle = '#F44336';
                    ctx.shadowBlur = 10;
                    ctx.shadowColor = '#F44336';
                    ctx.fillRect(this.food.x * CELL_SIZE + 2, this.food.y * CELL_SIZE + 2, CELL_SIZE - 4, CELL_SIZE - 4);
                    ctx.shadowBlur = 0;

                    // Draw Snake
                    this.snake.forEach((segment, index) => {
                        ctx.fillStyle = index === 0 ? '#66BB6A' : '#4CAF50';
                        ctx.fillRect(segment.x * CELL_SIZE, segment.y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
                        // Segment border
                        ctx.strokeStyle = '#121212';
                        ctx.lineWidth = 1;
                        ctx.strokeRect(segment.x * CELL_SIZE, segment.y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
                    });
                }
            }

            // Initialize game
            gameInstance = new SnakeGame(CELL_COUNT, CELL_COUNT);

            // Expose API to window
            window.game = {
                w: CELL_COUNT,
                h: CELL_COUNT,
                reset: () => gameInstance.reset(),
                tick: () => gameInstance.tick(),
                setDir: (dir) => gameInstance.setDir(dir),
                setFood: (x, y) => gameInstance.setFood(x, y),
                snake: () => gameInstance.snake(),
                food: () => gameInstance.food(),
                alive: () => gameInstance.alive(),
                score: () => gameInstance.score()
            };

            // Control Logic
            let gameInterval = null;

            function startLoop() {
                if (gameInterval) clearInterval(gameInterval);
                gameInterval = setInterval(() => {
                    gameInstance.tick();
                    if (!gameInstance.alive()) {
                        clearInterval(gameInterval);
                        gameInterval = null;
                    }
                }, 150);
            }

            startBtn.addEventListener('click', () => {
                if (!gameInstance.isAlive) gameInstance.reset();
                startLoop();
            });

            pauseBtn.addEventListener('click', () => {
                clearInterval(gameInterval);
                gameInterval = null;
            });

            resetBtn.addEventListener('click', () => {
                clearInterval(gameInterval);
                gameInterval = null;
                gameInstance.reset();
            });

            // Keyboard Controls
            window.addEventListener('keydown', (e) => {
                switch(e.key) {
                    case 'ArrowUp':    gameInstance.setDir('up'); break;
                    case 'ArrowDown':  gameInstance.setDir('down'); break;
                    case 'ArrowLeft':  gameInstance.setDir('left'); break;
                    case 'ArrowRight': gameInstance.setDir('right'); break;
                }
            });

        })();
    </script>
</body>
</html>

